// 五个具名政治命令的严格边界，未知参数拒绝；不提供任意公职字段setter。
#include "politics_views.hpp"
#include <set>
namespace hanmo::resident {
namespace {
using V=BoundaryValue;using D=V::Dict;
// 命令键集合必须恰好匹配，旧按钮缺版本也不能以默认零继续。
void keys(const V& v,std::initializer_list<const char*> names){std::set<StableId> wanted;for(const auto* name:names)wanted.insert(name);for(const auto& row:boundary::object(v,"/params"))if(!wanted.erase(row.first))boundary::fail("UnknownPoliticalCommandField","/params/"+row.first);if(!wanted.empty())boundary::fail("MissingPoliticalCommandField","/params/"+*wanted.begin());}
// 签发者由值边界表示，实际权限始终在候选重验。
ActingAuthority authority(const V& v){keys(v,{"organization_id","office_id","authority_epoch","actor_id"});return {boundary::get_string(v,"organization_id","/authority"),boundary::get_string(v,"office_id","/authority"),boundary::get_int(v,"authority_epoch","/authority"),boundary::get_string(v,"actor_id","/authority")};}
V authority(const ActingAuthority& a){return boundary::obj({{"organization_id",V{a.organization_id}},{"office_id",V{a.office_id}},{"authority_epoch",V{a.authority_epoch}},{"actor_id",V{a.actor_id}}});}
}
StableId politics_command_kind(const PoliticsCommand& command){return std::visit([](const auto& cmd)->StableId{using T=std::decay_t<decltype(cmd)>;if constexpr(std::is_same_v<T,PoliticalAppointCommand>)return "political_appoint";if constexpr(std::is_same_v<T,PoliticalAnswerAppointmentCommand>)return "political_answer_appointment";if constexpr(std::is_same_v<T,PoliticalArriveCommand>)return "political_arrive";if constexpr(std::is_same_v<T,PoliticalWithdrawCommand>)return "political_withdraw_appointment";return "political_dismiss";},command);}
BoundaryValue encode_politics_command(const PoliticsCommand& command){return std::visit([](const auto& c)->V{using T=std::decay_t<decltype(c)>;if constexpr(std::is_same_v<T,PoliticalAppointCommand>)return boundary::obj({{"authority",authority(c.authority)},{"jurisdiction_id",V{c.jurisdiction_id}},{"target_actor_id",V{c.target_actor_id}},{"policy_id",V{c.policy_id}},{"expected_jurisdiction_revision",V{c.expected_jurisdiction_revision}},{"expected_office_epoch",V{c.expected_office_epoch}}});else if constexpr(std::is_same_v<T,PoliticalAnswerAppointmentCommand>)return boundary::obj({{"actor_id",V{c.actor_id}},{"appointment_id",V{c.appointment_id}},{"expected_revision",V{c.expected_revision}},{"accept",V{c.accept}},{"source_fact_id",V{c.source_fact_id}}});else if constexpr(std::is_same_v<T,PoliticalArriveCommand>)return boundary::obj({{"actor_id",V{c.actor_id}},{"appointment_id",V{c.appointment_id}},{"expected_revision",V{c.expected_revision}},{"source_fact_id",V{c.source_fact_id}}});else if constexpr(std::is_same_v<T,PoliticalWithdrawCommand>)return boundary::obj({{"authority",authority(c.authority)},{"appointment_id",V{c.appointment_id}},{"expected_revision",V{c.expected_revision}}});else return boundary::obj({{"authority",authority(c.authority)},{"jurisdiction_id",V{c.jurisdiction_id}},{"expected_jurisdiction_revision",V{c.expected_jurisdiction_revision}},{"expected_office_epoch",V{c.expected_office_epoch}}});},command);}
Outcome<PoliticsCommand> decode_politics_command(const StableId& kind,const V& v){try{auto str=[&](const char* key){return boundary::get_string(v,key,"/params");};auto num=[&](const char* key){return boundary::get_int(v,key,"/params");};if(kind=="political_appoint"){keys(v,{"authority","jurisdiction_id","target_actor_id","policy_id","expected_jurisdiction_revision","expected_office_epoch"});return {true,PoliticalAppointCommand{authority(boundary::field(v,"authority","/params")),str("jurisdiction_id"),str("target_actor_id"),str("policy_id"),num("expected_jurisdiction_revision"),num("expected_office_epoch")},{}};}if(kind=="political_answer_appointment"){keys(v,{"actor_id","appointment_id","expected_revision","accept","source_fact_id"});return {true,PoliticalAnswerAppointmentCommand{str("actor_id"),str("appointment_id"),num("expected_revision"),boundary::boolean(boundary::field(v,"accept","/params"),"/params/accept"),str("source_fact_id")},{}};}if(kind=="political_arrive"){keys(v,{"actor_id","appointment_id","expected_revision","source_fact_id"});return {true,PoliticalArriveCommand{str("actor_id"),str("appointment_id"),num("expected_revision"),str("source_fact_id")},{}};}if(kind=="political_withdraw_appointment"){keys(v,{"authority","appointment_id","expected_revision"});return {true,PoliticalWithdrawCommand{authority(boundary::field(v,"authority","/params")),str("appointment_id"),num("expected_revision")},{}};}if(kind=="political_dismiss"){keys(v,{"authority","jurisdiction_id","expected_jurisdiction_revision","expected_office_epoch"});return {true,PoliticalDismissCommand{authority(boundary::field(v,"authority","/params")),str("jurisdiction_id"),num("expected_jurisdiction_revision"),num("expected_office_epoch")},{}};}return {false,{},common_failure("UnsupportedPoliticalCommand",kind,ErrorKind::unsupported_capability).error};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
} // 命令族保持闭合，SDK不得通过params夹带隐藏世界修改。
